import { getModelFile, fromUrls } from 'parakeet.js';

// BlackRiver Voice 1.4: Parakeet TDT is the speech recognizer.  The previous
// This worker intentionally does one job only: turn 16 kHz mono PCM into a
// faithful multilingual transcript. Natural/Prompt shaping lives in a separate
// tiny Wllama sidecar so ASR quality can be tested independently.
const PARAKEET_REPO = 'efederici/parakeet-tdt-0.6b-v3-onnx-int4';
const PARAKEET_FILES = {
  encoder: 'encoder-model.int4.onnx',
  decoder: 'decoder_joint-model.int8.onnx',
  tokenizer: 'vocab.txt',
};

let model = null;
let loadPromise = null;

function safePost(message) {
  self.postMessage(message);
}

function cleanTranscript(text = '') {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;!?])/g, '$1')
    .trim();
}

function makeAggregateProgress(requestId) {
  const byFile = new Map();
  return ({ loaded = 0, total = 0, file = '' } = {}) => {
    byFile.set(file || 'model', {
      loaded: Number.isFinite(loaded) ? loaded : 0,
      total: Number.isFinite(total) ? total : 0,
    });
    let sumLoaded = 0;
    let sumTotal = 0;
    for (const entry of byFile.values()) {
      sumLoaded += entry.loaded;
      sumTotal += entry.total;
    }
    safePost({
      type: 'progress',
      requestId,
      stage: 'parakeet',
      label: 'Parakeet TDT',
      event: {
        file,
        loaded: sumLoaded,
        total: sumTotal,
        progress: sumTotal > 0 ? (sumLoaded / sumTotal) * 100 : null,
      },
    });
  };
}

async function ensureModel(requestId) {
  if (model) return model;
  if (loadPromise) return loadPromise;

  loadPromise = (async () => {
    if (!navigator.gpu) throw new Error('BlackRiver Voice requires WebGPU in this browser.');
    safePost({ type: 'phase', requestId, phase: 'loading-asr', label: 'Loading Parakeet TDT' });

    const progress = makeAggregateProgress(requestId);
    const [encoderUrl, decoderUrl, tokenizerUrl] = await Promise.all([
      getModelFile(PARAKEET_REPO, PARAKEET_FILES.encoder, { progress }),
      getModelFile(PARAKEET_REPO, PARAKEET_FILES.decoder, { progress }),
      getModelFile(PARAKEET_REPO, PARAKEET_FILES.tokenizer, { progress }),
    ]);

    const instance = await fromUrls({
      encoderUrl,
      decoderUrl,
      tokenizerUrl,
      filenames: {
        encoder: PARAKEET_FILES.encoder,
        decoder: PARAKEET_FILES.decoder,
      },
      backend: 'webgpu-hybrid',
      preprocessorBackend: 'js',
      nMels: 128,
      verbose: false,
      // Keep the decoder cheap and predictable. The encoder is WebGPU; decoder
      // runs on WASM by design in parakeet.js hybrid mode.
      cpuThreads: Math.max(1, Math.min(4, navigator.hardwareConcurrency || 4)),
    });

    model = instance;
    safePost({ type: 'phase', requestId, phase: 'asr-ready', label: 'Parakeet ready' });
    return instance;
  })();

  try {
    return await loadPromise;
  } finally {
    loadPromise = null;
  }
}

async function runTranscription(requestId, audioBuffer, settings = {}) {
  const instance = await ensureModel(requestId);
  const audio = new Float32Array(audioBuffer);
  const duration = audio.length / 16000;

  safePost({ type: 'phase', requestId, phase: 'transcribing', label: 'Transcribing with Parakeet' });

  let result;
  if (duration > 55) {
    result = await instance.transcribeLongAudio(audio, 16000, {
      returnTimestamps: false,
      chunkLengthS: 50,
    });
  } else {
    result = await instance.transcribe(audio, 16000, {
      returnTimestamps: false,
      returnConfidences: true,
    });
  }

  const raw = cleanTranscript(result?.utterance_text ?? result?.text ?? '');
  safePost({ type: 'raw', requestId, raw, asr: 'parakeet-tdt-0.6b-v3' });
  safePost({
    type: 'result',
    requestId,
    raw,
    cleaned: raw,
    mode: settings.mode === 'raw' ? 'raw' : settings.mode === 'prompt' ? 'prompt' : 'natural',
    asr: 'parakeet-tdt-0.6b-v3',
    needsRefine: settings.mode !== 'raw',
    metrics: result?.metrics || null,
  });
}

self.onmessage = async ({ data }) => {
  const requestId = data?.requestId;
  try {
    if (data?.type === 'load') {
      await ensureModel(requestId);
      safePost({ type: 'ready', requestId });
      return;
    }
    if (data?.type === 'transcribe') {
      await runTranscription(requestId, data.audio, data.settings || {});
    }
  } catch (error) {
    safePost({
      type: 'error',
      requestId,
      message: error?.message || String(error) || 'BlackRiver Voice failed.',
      name: error?.name || 'Error',
    });
  }
};
